        const b = point(rings[ring + 1], step);
        const c = point(rings[ring], step + 1);
        const d = point(rings[ring + 1], step + 1);
        const slope = (rings[ring + 1][1] - rings[ring][1]) / (rings[ring][0] - rings[ring + 1][0]);
        const normal = at => normalize([Math.sin(at), slope, Math.cos(at)]);
